import { App, normalizePath } from 'obsidian'

import { DEFAULT_PROMPTS_FOLDER, DEFAULT_WORKFLOWS_FOLDER } from '../constants'

import { seedReportWorkspace } from './seedReportWorkspace'
import bundle from './starterAssets.json'
import { ensureVaultDir } from './vault'

/**
 * The default Skills, Workflows and Prompts that ship inside the plugin
 * (generated by scripts/build-starter-assets.mjs), in Korean and, for the
 * sets that are not tied to Korean documents, in English. They are offered
 * to the user and written only on request. A file the user may have written
 * is never replaced.
 */

export type StarterKind = 'skill' | 'workflow' | 'prompt'
export type StarterLocale = 'ko' | 'en'
export type StarterFile = { kind: StarterKind; path: string; content: string }
export type StarterPack = {
  id: StarterPackId
  files: Record<StarterLocale, StarterFile[]>
}
export const STARTER_PACK_IDS = [
  'writing',
  'obsidian',
  'data',
  'documents',
] as const
export type StarterPackId = (typeof STARTER_PACK_IDS)[number]

export type StarterFolders = {
  skillsFolder: string
  workflowsFolder: string
  promptsFolder: string
}

export const STARTER_PACKS = bundle.packs as StarterPack[]

/**
 * The files of a set in one language. The report workflow and its prompts
 * are the plugin's own (the ones a first start writes), so a vault that lost
 * them, or has them in the other language, can get them here too.
 */
export function starterFiles(
  pack: StarterPack,
  locale: StarterLocale,
): StarterFile[] {
  if (pack.id !== 'writing') return pack.files[locale]
  const seed = seedReportWorkspace(locale)
  return [
    ...pack.files[locale],
    { kind: 'workflow', path: 'report.workflow.yaml', content: seed.workflow },
    { kind: 'prompt', path: 'collect.md', content: seed.collect },
    { kind: 'prompt', path: 'draft.md', content: seed.draft },
  ]
}

/** The folder where the first start puts its one seed skill. */
const SEED_SKILL = 'report-writing'

const sameText = (a: string, b: string) =>
  a.replace(/\r\n/g, '\n').trim() === b.replace(/\r\n/g, '\n').trim()

/**
 * What the first start writes (bootstrap.ts), in either language. An
 * untouched copy is a placeholder, not the user's work, so the fuller
 * bundled file may take its place.
 */
const isSeed = (content: string) =>
  (['ko', 'en'] as const).some((locale) =>
    Object.values(seedReportWorkspace(locale)).some((seed) =>
      sameText(seed, content),
    ),
  )

/**
 * Resolves the three folders the way the loaders read them, and refuses a
 * setting that would write somewhere the loaders never look.
 */
export function starterFolders(folders: StarterFolders): StarterFolders {
  const resolve = (value: string, fallback = '') => {
    const set = value.trim()
    const folder = normalizePath(set === '' ? fallback : set).replace(
      /^\/+|\/+$/g,
      '',
    )
    if (
      !folder ||
      /^[A-Za-z]:/.test(folder) ||
      folder.split('/').some((part) => part === '..' || part === '.')
    )
      throw new Error(`Folder setting cannot be used: "${value}"`)
    return folder
  }
  return {
    // An empty skills folder means "no skills" to the loader.
    skillsFolder: resolve(folders.skillsFolder),
    workflowsFolder: resolve(folders.workflowsFolder, DEFAULT_WORKFLOWS_FOLDER),
    promptsFolder: resolve(folders.promptsFolder, DEFAULT_PROMPTS_FOLDER),
  }
}

export const starterTarget = (folders: StarterFolders, file: StarterFile) =>
  `${
    file.kind === 'skill'
      ? folders.skillsFolder
      : file.kind === 'workflow'
        ? folders.workflowsFolder
        : folders.promptsFolder
  }/${file.path}`

/** A skill is a folder; its name is the first path segment. */
const skillName = (file: StarterFile) => file.path.split('/')[0]

/**
 * `stock`: an untouched file this plugin wrote, as a first-start placeholder
 * or as the same asset in the other language. It is not the user's work, so
 * an install may replace it.
 */
type Presence = 'missing' | 'stock' | 'present'

const otherLocale = (locale: StarterLocale): StarterLocale =>
  locale === 'ko' ? 'en' : 'ko'

async function presence(
  app: App,
  target: string,
  file: StarterFile,
  counterpart?: StarterFile,
): Promise<Presence> {
  const adapter = app.vault.adapter
  if (!(await adapter.exists(target))) return 'missing'
  try {
    const content = await adapter.read(target)
    // Already what would be written.
    if (sameText(content, file.content)) return 'present'
    return isSeed(content) ||
      (counterpart && sameText(content, counterpart.content))
      ? 'stock'
      : 'present'
  } catch {
    return 'present'
  }
}

/** The same asset (same kind and path) in the other language, if any. */
const counterpartOf = (
  pack: StarterPack,
  locale: StarterLocale,
  file: StarterFile,
) =>
  starterFiles(pack, otherLocale(locale)).find(
    (other) => other.kind === file.kind && other.path === file.path,
  )

export type StarterPackStatus = {
  id: StarterPackId
  skills: number
  workflows: number
  prompts: number
  /** Files offered in the chosen language; 0 when the set has none. */
  files: number
  /** Files already in the vault (an untouched placeholder is not one). */
  existing: number
  skillNames: string[]
}

export async function starterStatus(
  app: App,
  rawFolders: StarterFolders,
  locale: StarterLocale,
): Promise<StarterPackStatus[]> {
  const folders = starterFolders(rawFolders)
  return Promise.all(
    STARTER_PACKS.map(async (pack) => {
      const files = starterFiles(pack, locale)
      const found = await Promise.all(
        files.map((file) =>
          presence(
            app,
            starterTarget(folders, file),
            file,
            counterpartOf(pack, locale, file),
          ),
        ),
      )
      const skillNames = [
        ...new Set(
          files.filter((file) => file.kind === 'skill').map(skillName),
        ),
      ]
      return {
        id: pack.id,
        skills: skillNames.length,
        workflows: files.filter((file) => file.kind === 'workflow').length,
        prompts: files.filter((file) => file.kind === 'prompt').length,
        files: files.length,
        existing: found.filter((state) => state === 'present').length,
        skillNames,
      }
    }),
  )
}

/**
 * True for a new install, or a reinstall after the folders were removed:
 * the skills folder holds nothing but the untouched seed skill. A vault with
 * skills of its own, or an edited seed, is in use and is left in peace.
 */
export async function looksUnprovisioned(
  app: App,
  rawFolders: StarterFolders,
): Promise<boolean> {
  let folders: StarterFolders
  try {
    folders = starterFolders(rawFolders)
  } catch {
    return false
  }
  const adapter = app.vault.adapter
  if (await adapter.exists(folders.skillsFolder)) {
    const listed = await adapter.list(folders.skillsFolder)
    // Loose files (a README, .DS_Store) are not skills.
    const own = listed.folders
      .map((path) => path.replace(/\/+$/, '').split('/').pop())
      .filter((name) => name !== SEED_SKILL)
    if (own.length > 0) return false
  }
  const seed = `${folders.skillsFolder}/${SEED_SKILL}/SKILL.md`
  return !(await adapter.exists(seed)) || isSeed(await adapter.read(seed))
}

export type StarterInstallResult = {
  written: string[]
  /** Already there, and not an untouched placeholder: left as it was. */
  kept: string[]
  failed: { path: string; error: string }[]
}

export async function installStarterPacks(
  app: App,
  rawFolders: StarterFolders,
  packIds: readonly StarterPackId[],
  locale: StarterLocale,
): Promise<StarterInstallResult> {
  const folders = starterFolders(rawFolders)
  const result: StarterInstallResult = { written: [], kept: [], failed: [] }
  for (const pack of STARTER_PACKS) {
    if (!packIds.includes(pack.id)) continue
    for (const file of starterFiles(pack, locale)) {
      const target = starterTarget(folders, file)
      try {
        const state = await presence(
          app,
          target,
          file,
          counterpartOf(pack, locale, file),
        )
        if (state === 'present') {
          result.kept.push(target)
          continue
        }
        await ensureVaultDir(app, target.slice(0, target.lastIndexOf('/')))
        await app.vault.adapter.write(target, file.content)
        result.written.push(target)
      } catch (error) {
        result.failed.push({
          path: target,
          error: error instanceof Error ? error.message : String(error),
        })
      }
    }
  }
  return result
}
